const proxyUpgrade = (req, socket, head) => {
  if (!proxy?.target) return false;
  try {
    proxyWss.handleUpgrade(req, socket, head, (local) => {
      const upstream = new WebSocket(proxy.target, { handshakeTimeout: 8000, maxPayload: WS_MAX_PAYLOAD });
      const close = () => { try { local.close(); } catch {} try { upstream.terminate(); } catch {} };
      local.on('message', (data, isBinary) => { if (upstream.readyState === WebSocket.OPEN) upstream.send(data, { binary: isBinary }); });
      local.on('close', close); local.on('error', close);
      upstream.on('message', (data, isBinary) => { if (local.readyState === WebSocket.OPEN) local.send(data, { binary: isBinary }); });
      upstream.on('error', close); upstream.on('close', close);
    });
    return true;
  } catch (error) { log.error('[ws] proxy upgrade failed', error); try { socket.destroy(); } catch {} return true; }
};

